;; docs/theory/12 §2.4: what the restart guard does and does NOT cover.
;;
;; Enumerate every TRUE deck of 1..max-n pages in a family — a sequence of page roles and frame numbers generated by
;; Beamer's labelling rules as ADR-0048 §2.1 states them (a slide carries its frame number, an overlay keeps it, a new
;; frame steps it by one, a note page carries its physical page number i + 1), extended by changes of the frame
;; counter by hand — compute its labels, and run the code's own `interleaving` and `restartable?` (loaded verbatim from
;; notes.cljs). A trusted producer (pdfTeX, LuaTeX) hides the proven note pages AT ONCE exactly when the status is
;; :proven and the labels are not restartable (notes.cljs `plan`). Count every such deck whose proven note pages
;; differ from its true ones, and compare every count with the closed forms of docs/theory/12 §2.4.
;;
;; usage: clojure -M restart_guard.clj <family> <max-n> [examples]
;;   family: none | appendix | drops | drops-L0-by-hand | forward
;; Prints one tally per line; a line whose key is in CAPITALS is a violation. Exits 1 when there is one.
(load-file (str (.getParent (.getAbsoluteFile (java.io.File. (str *file*)))) "/notes_extract.clj"))
(notes-extract/load-notes!)

(def family (keyword (or (first *command-line-args*) "appendix")))
(def max-n (Long/parseLong (or (second *command-line-args*) "8")))
(def max-examples (Long/parseLong (or (nth *command-line-args* 2 nil) "12")))

;; ---- the families -------------------------------------------------------------------------------------------------
;; Each family names the first page's label (the start), and the slide labels a CHANGE of the counter may give at page
;; i when the current frame number is f. A change's label is never f or f + 1: those are an overlay and a new frame.
;;   none              no change (the rules of ADR-0048 §2.1 exactly): the sanity family
;;   appendix          at most one restart, to label 1 (`appendixnumberbeamer` sets the counter to 0 at \appendix)
;;   drops             any number of restarts, each to any label below the current frame (a counter set back by hand)
;;   drops-L0-by-hand  as drops, and the counter is also set by hand before the first frame (L0 in 2..3)
;;   forward           any number of changes FORWARD by hand, to any label in f + 2 .. max-n + 1 (outside the guard's
;;                     design: these are jumps, not restarts)

(def spec
  (case family
    :none             {:starts [0 1]   :max-changes 0  :values (fn [_f _n] [])}
    :appendix         {:starts [0 1]   :max-changes 1  :values (fn [f _n] (if (>= f 2) [1] []))}
    :drops            {:starts [0 1]   :max-changes 99 :values (fn [f _n] (range 0 f))}
    :drops-L0-by-hand {:starts [2 3]   :max-changes 99 :values (fn [f _n] (range 0 f))}
    :forward          {:starts [0 1]   :max-changes 99 :values (fn [f n] (range (+ f 2) (+ n 2)))}))

;; ---- the closed forms of §2.4 -------------------------------------------------------------------------------------

(defn pow ^long [b e] (reduce * 1 (repeat e b)))
(defn binom2 ^long [k] (quot (* k (dec k)) 2))

(defn proven-restart-decks
  "P(n): the n-page decks with one restart, to label 1, that the automaton proves: (3^(n-1) - 2n + 1) / 4."
  [n] (if (< n 2) 0 (quot (+ (- (pow 3 (dec n)) (* 2 n)) 1) 4)))
(defn confirmed-restart-decks
  "C(n): those whose labels are restartable, so even a trusted producer confirms them: 2^(n-1) - n."
  [n] (if (< n 2) 0 (- (pow 2 (dec n)) n)))
(defn wrong-at-once
  "W(n): those a trusted producer hides at once, all wrongly: sum over the restart page i of (i - 1)(3^(n-i-1) -
   2^(n-i-1)), which equals P(n) - C(n)."
  [n] (reduce + 0 (for [i (range 2 (dec n))] (* (dec i) (- (pow 3 (- n i 1)) (pow 2 (- n i 1)))))))
(defn ambiguous-restart-decks
  "A(n): the n-page decks with one restart to a label v >= 2 below the frame (drops family): sum over i of
   C(i - 1, 2) 3^(n-i-1)."
  [n] (reduce + 0 (for [i (range 3 n)] (* (binom2 (dec i)) (pow 3 (- n i 1))))))
(defn confirmed-plain-decks
  "The restart-free decks (L0 <= 1) that the automaton proves but the guard sends to CONFIRM: 2^(n-2) - 1."
  [n] (if (< n 2) 0 (dec (pow 2 (- n 2)))))
(defn twin-plain-decks
  "The restart-free decks whose labels are those of a W(n) deck (theory/12 §2.4.9): L0 = 1, pages 1 … m note pages
   of page 0 (m >= 1), an overlay of frame 1 at page m + 1, and a note page somewhere after it:
   (3^(n-2) - 1)/2 - (2^(n-2) - 1)."
  [n] (if (< n 2) 0 (- (quot (dec (pow 3 (- n 2))) 2) (dec (pow 2 (- n 2))))))

;; ---- the idealized default template (used only to say what CONFIRM and the probe would decide) ---------------------
;; SIG(s, j) is true exactly when j is a true note page and s is the slide it annotates (the last true slide before
;; it): assumptions T1-T3 of docs/theory/12 §4. ROTATED-DATE(j) is true exactly when j is a true note page drawn by
;; the default template (T4).

(defn true-slide-of [roles j] (last (filter #(= :slide (nth roles %)) (range j))))

(defn oracle-confirm
  "CONFIRM over note pages `ps` (the code's confirm-pairs and confirmed?), with the idealized default template."
  [roles ps]
  (let [n (count roles)]
    (every? (fn [[s j]]
              (let [note? (= :note (nth roles j))]
                (notes/confirmed? (and note? (= s (true-slide-of roles j))) note?)))
            (notes/confirm-pairs n ps))))

(defn oracle-probe
  "The probe (the code's probe-next) over an :ambiguous interleaving `il`, with the idealized template: `dated?` is
   whether the template draws the date (default: yes; compressed: no). Returns {:note-pages ps :via v :reads r},
   r the distinct pages the walk read."
  [roles il dated-template?]
  (loop [seen [], read #{}]
    (let [mv (notes/probe-next il seen)]
      (if-let [a (:read mv)]
        (let [note? (= :note (nth roles a))]
          (recur (conj seen {:sig (and note? (= (dec a) (true-slide-of roles a)))
                             :dated? (and dated-template? note?)})
                 (conj read (dec a) a)))
        (assoc mv :reads (count read))))))

(defn verdict
  "What the audience is shown wrongly when `hidden` is hidden and `truth` are the true note pages."
  [hidden truth]
  (let [hidden (set hidden)]
    (cond (= hidden truth) :correct
          (some (complement truth) hidden) :HIDES-A-SLIDE
          (empty? hidden) :nothing-hidden
          :else :shows-some-note-pages)))

;; ---- enumeration --------------------------------------------------------------------------------------------------

(def tally (atom (sorted-map)))
(def violations (atom 0))
(defn bump! [k] (swap! tally update k (fnil inc 0)))
(defn violation! [k & info]
  (swap! violations inc)
  (bump! [k])
  (when (<= (get @tally [k]) 5) (apply println k info)))
(def examples (atom []))
(def probe-examples (atom []))
(def wrong-labels (atom {}))      ; n -> the label sequences of the decks hidden at once wrongly (restart families)
(def twin-labels (atom {}))       ; n -> the label sequences of the restart-free decks of the twin shape

(defn plain-run-end
  "The last page k of the deck's initial run of slides 0 … k labelled 1 … k + 1 (nil when page 0 is not labelled 1)."
  [labels roles]
  (last (take-while #(and (= :slide (nth roles %)) (= (inc %) (nth labels %))) (range (count labels)))))

(defn process!
  "One true deck: its labels, roles (:slide/:note) and the pages where the counter was changed by hand."
  [labels roles changes]
  (let [n (count labels)
        truth (into #{} (filter #(= :note (nth roles %))) (range n))
        il (notes/interleaving labels)
        st (:status il)
        rs? (notes/restartable? labels)
        tag (if (seq changes) :changed :plain)]
    (bump! [n :decks])
    (bump! [n tag :decks])
    (bump! [n tag :status st])
    (when (and (= :proven st) rs?) (bump! [n tag :routed-to-confirm]))
    ;; the probe under the idealized templates (docs/theory/12 §4), trusted (no CONFIRM after it) and not trusted
    ;; (CONFIRM after it, which the default template's date always passes for a true note page)
    (when (= :ambiguous st)
      (doseq [[tname dated?] [[:default true] [:compressed false]]]
        (let [{ps :note-pages reads :reads} (oracle-probe roles il dated?)
              hidden-trusted (or ps #{})
              hidden-untrusted (if (and (seq ps)
                                        (every? (fn [[s j]]
                                                  (let [note? (= :note (nth roles j))]
                                                    (notes/confirmed? (and note? (= s (true-slide-of roles j)))
                                                                      (and dated? note?))))
                                                (notes/confirm-pairs n ps)))
                                 ps #{})]
          (bump! [n tag :probe tname :trusted (verdict hidden-trusted truth)])
          (bump! [n tag :probe tname :untrusted (verdict hidden-untrusted truth)])
          ;; §4: inside the rules (and with restarts) the probe never hides a slide; a FORWARD change of the counter is
          ;; outside them, so there it is only counted, with a few examples
          (when (= :HIDES-A-SLIDE (verdict hidden-trusted truth))
            (if (= family :forward)
              (when (and (= tname :default) (< (count @probe-examples) max-examples))
                (swap! probe-examples conj {:labels labels :roles (apply str (map #(if (= :note %) "N" "S") roles))
                                            :changes changes :true-notes (vec (sort truth))
                                            :probe-hides (vec (sort ps))}))
              (violation! :PROBE-HID-A-SLIDE labels roles)))
          (when (= :HIDES-A-SLIDE (verdict hidden-untrusted truth)) (violation! :PROBE-AND-CONFIRM-HID-A-SLIDE labels roles))
          ;; the walk's cost against the trailing note pages t of a deck whose labels read 1 2 ... n
          (when (and (= :plain tag) (= labels (vec (range 1 (inc n)))))
            (let [t (count (take-while #(= :note (nth roles %)) (reverse (range n))))
                  predicted (if (= tname :default) (max 2 (inc t)) 2)]
              (bump! [n :plain :probe tname :plain-run-reads (keyword (str "trailing-notes-" t "-reads-" reads))])
              (when-not (= reads predicted) (violation! :PROBE-COST-MISPREDICTED labels roles tname reads)))))))
    ;; the restart-free decks the guard sends to CONFIRM (§2.4): page 0 a slide with m >= 1 note pages, then an
    ;; overlay of frame 1 at page m + 1, and no other note page
    (when (and (= :plain tag) (<= (first labels) 1) (= :proven st) rs?)
      (let [m (count (take-while #(= :note (nth roles %)) (range 1 n)))]
        (when-not (and (= 1 (first labels)) (>= m 1) (< (inc m) n) (= 1 (nth labels (inc m)))
                       (= truth (set (range 1 (inc m)))))
          (violation! :CONFIRMED-PLAIN-SHAPE-VIOLATED labels roles))))
    (when (and (= :proven st) (not rs?))
      (let [proven (:note-pages il)]
        (bump! [n tag :hidden-at-once])
        ;; §2.4.9: no rule on the labels and the Producer alone separates a wrongly hidden restart deck from the
        ;; restart-free deck with the same labels, which is hidden rightly
        (when (and (= :changed tag) (#{:appendix :drops} family))
          (swap! wrong-labels update n (fnil conj #{}) labels))
        (when (and (= :plain tag) (= 1 (first labels)) (contains? proven 1)
                   (= 1 (some->> (range 1 n) (remove proven) first (nth labels))))
          (bump! [n :plain :hidden-at-once :twin-shape])
          (swap! twin-labels update n (fnil conj #{}) labels))
        (if (= proven truth)
          (bump! [n tag :hidden-at-once :correct])
          (let [hides-slide? (boolean (some (complement truth) proven))
                shows-note? (boolean (some (complement proven) truth))]
            (bump! [n tag :hidden-at-once :WRONG])
            (bump! [n tag :hidden-at-once :WRONG (cond (and hides-slide? shows-note?) :hides-a-slide-and-shows-a-note
                                                       hides-slide? :hides-a-slide
                                                       :else :shows-a-note-page)])
            (bump! [n tag :hidden-at-once :WRONG (if (oracle-confirm roles proven)
                                                    :ideal-confirm-would-accept
                                                    :ideal-confirm-would-reject)])
            (when (#{:appendix :drops} family)
              (bump! [n tag :hidden-at-once :WRONG :by-restart-page (first changes)]))
            (when (< (count @examples) max-examples)
              (swap! examples conj {:labels labels
                                    :roles (apply str (map #(if (= :note %) "N" "S") roles))
                                    :changes changes :true-notes (vec (sort truth)) :proven (vec (sort proven))}))))))
    ;; §2.4: the restart lemma and the classification of restart decks (L0 <= 1, every change a drop)
    (when (and (#{:appendix :drops} family) (seq changes))
      (let [parses (case st
                     :proven [(:note-pages il)]
                     :none [#{}]
                     :ambiguous (cond-> (mapv #(notes/candidate-notes il %) (:candidates il))
                                  (:fallback? il) (conj (:base il)))
                     [])]
        ;; the restart lemma: every valid parse reads the last true slide before a restart as a note page
        (doseq [p parses
                i changes]
          (when-not (contains? p (true-slide-of roles i))
            (violation! :RESTART-LEMMA-VIOLATED labels roles changes p)))
        (when (seq parses) (bump! [n :changed :has-a-valid-parse]))
        ;; the classification: several restarts → :invalid; one restart at i after the true slide s → :invalid unless
        ;; L_s = s + 1, and then by the restart's label v: 0 → :invalid, 1 → :proven, ≥ 2 → :ambiguous
        (let [[i & more] changes
              s (true-slide-of roles i)
              v (nth labels i)
              predicted (cond more :invalid
                              (not= (nth labels s) (inc s)) :invalid
                              (= v 0) :invalid
                              (= v 1) :proven
                              :else :ambiguous)]
          (when more (bump! [n :changed :several-restarts (if (seq parses) :HAS-A-PARSE :invalid)]))
          (when-not (= st predicted) (violation! :RESTART-CLASSIFICATION-VIOLATED labels roles changes st predicted))
          ;; a proven restart deck reads pages 1 … i - 1 as note pages, keeps the true note pages after i, and so
          ;; hides exactly the slides 1 … s
          (when (= :proven st)
            (let [after (into #{} (filter #(> % i)) truth)]
              (when-not (and (= (:note-pages il) (into (set (range 1 i)) after))
                             (= (set (remove truth (:note-pages il))) (set (range 1 (inc s))))
                             (= s (plain-run-end labels roles)))
                (violation! :PROVEN-RESTART-SHAPE-VIOLATED labels roles changes)))))))))

(defn walk!
  "Depth-first over true decks: every prefix of a deck is a deck of its own length."
  [labels roles f changes]
  (process! labels roles changes)
  (let [i (count labels)]
    (when (< i max-n)
      (walk! (conj labels f) (conj roles :slide) f changes)                ; an overlay (or a noframenumbering frame)
      (walk! (conj labels (inc f)) (conj roles :slide) (inc f) changes)    ; a new frame (\againframe included)
      (walk! (conj labels (inc i)) (conj roles :note) f changes)           ; a note page: its physical page number
      (when (< (count changes) (:max-changes spec))
        (doseq [v ((:values spec) f max-n)
                :when (not (#{f (inc f)} v))]
          (walk! (conj labels v) (conj roles :slide) v (conj changes i)))))))

(doseq [s (:starts spec)]
  (walk! [s] [:slide] s []))

(println "family" family "max-n" max-n)
(doseq [[k v] @tally] (println k v))

(defn check-count! [what n observed predicted]
  (println " n" n what "observed" observed "predicted" predicted (if (= observed predicted) "ok" "MISMATCH"))
  (when-not (= observed predicted) (violation! :CLOSED-FORM-MISMATCH what n observed predicted)))

(println "closed forms:")
(doseq [n (range 1 (inc max-n))]
  (case family
    :none
    (do (check-count! "routed-to-confirm" n (get @tally [n :plain :routed-to-confirm] 0) (confirmed-plain-decks n))
        (check-count! "hidden-at-once-wrong" n (get @tally [n :plain :hidden-at-once :WRONG] 0) 0))
    (:appendix :drops)
    (do (check-count! "proven-restart-decks" n (get @tally [n :changed :status :proven] 0) (proven-restart-decks n))
        (check-count! "routed-to-confirm" n (get @tally [n :changed :routed-to-confirm] 0) (confirmed-restart-decks n))
        (check-count! "wrong-at-once" n (get @tally [n :changed :hidden-at-once :WRONG] 0) (wrong-at-once n))
        (check-count! "wrong-at-once = P - C" n (wrong-at-once n)
                      (- (proven-restart-decks n) (confirmed-restart-decks n)))
        (check-count! "wrong-at-once with the restart at page 2" n
                      (get @tally [n :changed :hidden-at-once :WRONG :by-restart-page 2] 0)
                      (if (>= n 4) (- (pow 3 (- n 3)) (pow 2 (- n 3))) 0))
        (check-count! "ambiguous-restart-decks" n (get @tally [n :changed :status :ambiguous] 0)
                      (if (= family :drops) (ambiguous-restart-decks n) 0))
        (check-count! "plain hidden-at-once-wrong" n (get @tally [n :plain :hidden-at-once :WRONG] 0) 0)
        (check-count! "restart-free decks of the twin shape" n
                      (get @tally [n :plain :hidden-at-once :twin-shape] 0) (twin-plain-decks n))
        (check-count! "wrong-at-once labels = twin-shape labels (1 = equal sets)" n
                      (if (= (get @wrong-labels n #{}) (get @twin-labels n #{})) 1 0) 1))
    nil))
(println "examples (hidden at once, wrongly):")
(doseq [e @examples] (println " " e))
(when (seq @probe-examples)
  (println "examples (the probe without CONFIRM hides a slide, default template):")
  (doseq [e @probe-examples] (println " " e)))
(println (if (pos? @violations) (str "VIOLATIONS " @violations) "no violation"))
(shutdown-agents)
(System/exit (if (pos? @violations) 1 0))
